-- Бэкап всех страниц урока перед правкой:
CREATE TABLE IF NOT EXISTS _kab_bk20260924_l1960_pages AS SELECT * FROM mdl_lesson_pages WHERE lessonid=1960;
UPDATE mdl_lesson_pages SET contents = CONVERT(X'' USING utf8mb4), timemodified = UNIX_TIMESTAMP() WHERE id=17879 AND lessonid=1960;
UPDATE mdl_lesson_pages SET contents = CONVERT(X'' USING utf8mb4), timemodified = UNIX_TIMESTAMP() WHERE id=17880 AND lessonid=1960;
UPDATE mdl_lesson_pages SET contents = CONVERT(X'' USING utf8mb4), timemodified = UNIX_TIMESTAMP() WHERE id=17881 AND lessonid=1960;
SELECT id, title, LENGTH(contents) len, (LENGTH(contents)-LENGTH(REPLACE(contents,'drive.google.com/file/d/','')))/24 n_clips, timemodified FROM mdl_lesson_pages WHERE lessonid=1960 ORDER BY id;
